import{_ as l,o as a,c as e,a2 as t}from"./chunks/framework.BXA5Pi9t.js";const c=JSON.parse('{"title":"Client Driven Geo-Redundancy for Ceph Object Storage - Yuval Lifshitz, IBM","description":"","frontmatter":{"title":"Client Driven Geo-Redundancy for Ceph Object Storage - Yuval Lifshitz, IBM","date":"2023-05-05T00:00:00.000Z","updated":"2023-05-05T00:00:00.000Z","tags":["Ceph Object Storage","Geo","Redundancy","Client Notifications","Distributed Storage","Data Replication"],"categories":["视频总结"],"outline":"deep"},"headers":[],"relativePath":"posts/2023/Client_Driven_Geo-Redundancy_for_Ceph_Object_Storage_-_Yuval_Lifshitz_IBM.md","filePath":"posts/2023/Client_Driven_Geo-Redundancy_for_Ceph_Object_Storage_-_Yuval_Lifshitz_IBM.md","lastUpdated":1780459816000}'),o={name:"posts/2023/Client_Driven_Geo-Redundancy_for_Ceph_Object_Storage_-_Yuval_Lifshitz_IBM.md"};function r(n,i,s,u,h,_){return a(),e("div",null,[...i[0]||(i[0]=[t('<h3 id="会议纪要" tabindex="-1">会议纪要 <a class="header-anchor" href="#会议纪要" aria-label="Permalink to &quot;会议纪要&quot;">​</a></h3><h4 id="会议主题-基于客户端的ceph对象存储地理冗余-yuval-lifshitz-ibm" tabindex="-1">会议主题：基于客户端的Ceph对象存储地理冗余 - Yuval Lifshitz, IBM <a class="header-anchor" href="#会议主题-基于客户端的ceph对象存储地理冗余-yuval-lifshitz-ibm" aria-label="Permalink to &quot;会议主题：基于客户端的Ceph对象存储地理冗余 - Yuval Lifshitz, IBM&quot;">​</a></h4><h4 id="会议时间-具体日期" tabindex="-1">会议时间：[具体日期] <a class="header-anchor" href="#会议时间-具体日期" aria-label="Permalink to &quot;会议时间：[具体日期]&quot;">​</a></h4><h4 id="参会人员" tabindex="-1">参会人员： <a class="header-anchor" href="#参会人员" aria-label="Permalink to &quot;参会人员：&quot;">​</a></h4><ul><li>Yuval（IBM，Redis Gateway项目负责人）</li><li>Liave和Omar（学生，参与项目开发）</li><li>其他相关技术人员</li></ul><h4 id="会议内容" tabindex="-1">会议内容： <a class="header-anchor" href="#会议内容" aria-label="Permalink to &quot;会议内容：&quot;">​</a></h4><ol><li><p><strong>项目背景</strong>：</p><ul><li>Yuval介绍了Redis Gateway项目，该项目是由Red Hat和Reichmann University在以色列的合作项目Connect的一部分。</li><li>感谢Liave和Omar两位学生在该项目中的贡献。</li></ul></li><li><p><strong>多站点复制的挑战</strong>：</p><ul><li>多站点设置在集群中复杂且问题常出，包括网络、性能、数据同步和集群间通信问题。</li><li>动态重分片等增加了系统的复杂性。</li></ul></li><li><p><strong>用户控制的需求</strong>：</p><ul><li>当前系统高度异步，用户难以了解数据何时安全同步。</li><li>项目旨在通过增加新的桶通知来增强用户对复制系统的控制。</li></ul></li><li><p><strong>解决方案介绍</strong>：</p><ul><li>在Redis Gateway中增加新的桶通知类型，通知用户对象何时安全同步到一个区域。</li><li>通过Kafka或其他通知机制，用户可以订阅这些通知并据此采取行动。</li></ul></li><li><p><strong>演示和实施细节</strong>：</p><ul><li>演示了如何在两个站点之间设置主题和通知，以及对象上传后如何在备份站点同步并发送通知。</li></ul></li><li><p><strong>后续改进和行动计划</strong>：</p><ul><li>需要改进多站点间的信息同步，特别是主题和通知的配置。</li><li>计划增加更多类型的通知事件，如删除事件和版本桶创建事件。</li><li>学生已经开始编写一个围绕Boto3 Python库的包装器，以简化端到端的功能。</li><li>鼓励社区成员参与完善和扩展这些功能。</li></ul></li><li><p><strong>问题与回答</strong>：</p><ul><li>讨论了通知的具体内容和如何自定义通知数据。</li><li>确认了通知机制与AWS S3的兼容性和扩展性。</li></ul></li></ol><h4 id="后续行动" tabindex="-1">后续行动： <a class="header-anchor" href="#后续行动" aria-label="Permalink to &quot;后续行动：&quot;">​</a></h4><ul><li>完善多站点间的信息同步机制。</li><li>增加更多类型的通知事件。</li><li>完成并发布Boto3 Python库的包装器。</li><li>社区成员参与测试和反馈，以进一步优化系统。</li></ul><h4 id="会议结束" tabindex="-1">会议结束： <a class="header-anchor" href="#会议结束" aria-label="Permalink to &quot;会议结束：&quot;">​</a></h4><ul><li>Yuval感谢大家的参与，并鼓励大家提出问题和建议。</li><li>会议在掌声中结束。</li></ul><p><strong>备注</strong>：本会议纪要基于Yuval的介绍和讨论内容整理，旨在记录会议的关键细节和后续行动计划。</p>',12)])])}const p=l(o,[["render",r]]);export{c as __pageData,p as default};
